public class Main {
    public static void main(String[] args) {
        Koleksi[] rak = {
            new Buku("Laskar Pelangi", "Andrea Hirata"),
            new Majalah("National Geographic", 250)
        };

        for (Koleksi k : rak) {
            k.info();
            if (k instanceof BisaDipinjam) {
                BisaDipinjam p = (BisaDipinjam) k;
                p.pinjam("Budi");
            }
        }
    }
}

interface BisaDipinjam {
    void pinjam(String nama);
}

abstract class Koleksi {
    private String judul;

    Koleksi(String judul) {
        this.judul = judul;
    }

    String getJudul() {
        return judul;
    }

    abstract void info();
}

class Buku extends Koleksi implements BisaDipinjam {
    private String penulis;

    Buku(String judul, String penulis) {
        super(judul);
        this.penulis = penulis;
    }

    @Override
    void info() {
        System.out.println("Buku: " + getJudul() + " oleh " + penulis);
    }

    public void pinjam(String nama) {
        System.out.println("Dipinjam oleh " + nama);
    }
}

class Majalah extends Koleksi {
    private int edisi;

    Majalah(String judul, int edisi) {
        super(judul);
        this.edisi = edisi;
    }

    @Override
    void info() {
        System.out.println("Majalah: " + getJudul() + " edisi " + edisi);
    }
}

