public class Main {
    public static void main(String[] args) {
        Keranjang k = new Keranjang();
        k.tambah(new Biasa("Kopi", 15000));
        k.tambah(new Promo("Roti", 10000));
        k.tambah(new Paket("Hemat", 25000));
        k.hapus("Roti");
        k.cetak();
        try {
            k.hapus("Susu");
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
