        int t = 0;
        for (Produk p : isi) {
            t += p.hargaAkhir();
        }
        return t;
    }

    void hapus(String nama) {
        for (int i = 0; i < isi.size(); i++) {
            if (isi.get(i).getNama().equals(nama)) {
